text:
/* Close icon styles */

moz-button.close {
  display: flex;
  margin: 0;

  &::part(button) {
    background-image: var(--icon-close) !important;
    -moz-context-properties: fill, stroke;
    fill: color-mix(in srgb, currentColor 20%, transparent);
    stroke: currentColor;
    inline-size: var(--close-icon-size);
    block-size: var(--close-icon-size);
  }
}
